import { useEffect, useState } from 'react';
import { SelectField, TextField } from './ui.jsx';

// Philippine address chosen from the official PSGC list, one level at a time:
// country, region, province, city or municipality, barangay. The lists are
// static files in /psgc, generated by scripts/build-psgc.js, and are loaded
// only when needed (one province's barangays at a time).
//
// value: { regionCode, area, municipalityCode, barangayCode, street }
//   area is the province code, or the region code for towns not in a province
//   (all of Metro Manila, and a few towns elsewhere).

const cache = {};
function loadJson(path) {
  cache[path] ??= fetch(`/psgc/${path}`).then((res) => {
    if (!res.ok) throw new Error('The address list could not be loaded. Check your connection and try again.');
    return res.json();
  }).catch((err) => {
    delete cache[path];
    throw err;
  });
  return cache[path];
}

function useJson(path) {
  const [state, setState] = useState({ data: null, error: '' });
  useEffect(() => {
    if (!path) { setState({ data: null, error: '' }); return undefined; }
    let current = true;
    setState((s) => ({ ...s, error: '' }));
    loadJson(path)
      .then((data) => current && setState({ data, error: '' }))
      .catch((err) => current && setState({ data: null, error: err.message }));
    return () => { current = false; };
  }, [path]);
  return state;
}

export const OTHER_TOWNS = 'Other towns and cities in this region';

// What the API expects: codes only; the server looks up the names.
export function addressBody(v) {
  const isProvince = v.area && v.area !== v.regionCode;
  return {
    regionCode: v.regionCode || '',
    provinceCode: isProvince ? v.area : '',
    municipalityCode: v.municipalityCode || '',
    barangayCode: v.barangayCode || '',
    street: v.street || '',
  };
}

// Starting value from a saved farmer address.
export function addressValue(a) {
  return {
    regionCode: a?.regionCode || '',
    area: a?.provinceCode || (a?.municipalityCode ? a.regionCode : '') || '',
    municipalityCode: a?.municipalityCode || '',
    barangayCode: a?.barangayCode || '',
    street: a?.street || '',
  };
}

export default function AddressPicker({ value, onChange }) {
  const regions = useJson('regions.json');
  const provinces = useJson(value.regionCode ? 'provinces.json' : null);
  const municipalities = useJson(value.regionCode ? 'municipalities.json' : null);
  const barangays = useJson(value.area && value.municipalityCode ? `barangays/${value.area}.json` : null);

  const regionProvinces = provinces.data?.[value.regionCode] ?? [];
  const regionTowns = municipalities.data?.[value.regionCode] ?? [];
  const noProvinces = provinces.data && regionProvinces.length === 0;

  // Metro Manila has no provinces: go straight to its cities.
  useEffect(() => {
    if (noProvinces && value.regionCode && value.area !== value.regionCode) {
      onChange({ ...value, area: value.regionCode, municipalityCode: '', barangayCode: '' });
    }
  }, [noProvinces, value, onChange]);

  const towns = municipalities.data?.[value.area] ?? [];
  const brgys = barangays.data?.[value.municipalityCode] ?? [];
  const error = regions.error || provinces.error || municipalities.error || barangays.error;
  const set = (patch) => onChange({ ...value, ...patch });
  const list = (rows, placeholder) => [['', placeholder], ...rows.map((r) => [r.code, r.name])];

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-2 gap-4">
        <SelectField label="Country" value="PH" onChange={() => {}} options={[['PH', 'Philippines']]} />
        <SelectField
          label="Region" value={value.regionCode} disabled={!regions.data}
          onChange={(e) => set({ regionCode: e.target.value, area: '', municipalityCode: '', barangayCode: '' })}
          options={list(regions.data ?? [], regions.data ? 'Choose a region' : 'Loading…')}
        />
        {!noProvinces && (
          <SelectField
            label="Province" value={value.area} disabled={!value.regionCode || !provinces.data}
            onChange={(e) => set({ area: e.target.value, municipalityCode: '', barangayCode: '' })}
            options={[
              ...list(regionProvinces, value.regionCode ? 'Choose a province' : 'Choose a region first'),
              // A few towns belong to a region but no province.
              ...(regionTowns.length && regionProvinces.length ? [[value.regionCode, OTHER_TOWNS]] : []),
            ]}
          />
        )}
        <SelectField
          label="City or municipality" value={value.municipalityCode} disabled={!value.area || !municipalities.data}
          onChange={(e) => set({ municipalityCode: e.target.value, barangayCode: '' })}
          options={list(towns, value.area ? 'Choose a city or municipality' : noProvinces ? 'Loading…' : 'Choose a province first')}
        />
        <SelectField
          label="Barangay" value={value.barangayCode} disabled={!value.municipalityCode || !barangays.data}
          onChange={(e) => set({ barangayCode: e.target.value })}
          options={list(brgys, !value.municipalityCode ? 'Choose a city or town first' : barangays.data ? 'Choose a barangay' : 'Loading…')}
          className={noProvinces ? '' : 'col-span-2'}
        />
      </div>
      <TextField
        label="House no., street, purok, or sitio (optional)" value={value.street}
        onChange={(e) => set({ street: e.target.value })} maxLength={120}
      />
      {error && <p role="alert" className="text-sm text-critical">{error}</p>}
    </div>
  );
}
